x_938076_backup_0_backup_scripts.script:
setBulkCaseReqAttribute('number', 'display', false);
setBulkCaseReqAttribute('hr_service', 'read_only', false);
setBulkCaseReqAttribute('hr_service', 'mandatory', 'true');
setBulkCaseReqAttribute('opened_for', 'display', false);
setBulkCaseReqAttribute('opened_for', 'read_only', false);
setBulkCaseReqAttribute('status', 'default_value', 'draft');

function setBulkCaseReqAttribute(element, attribute, value) {
	var gr = new GlideRecord('sys_dictionary');
	gr.addQuery('name', 'sn_hr_core_bulk_case_request');
	gr.addQuery('element', element);
	gr.setLimit(1);
	gr.query();
	if (gr.next()) {
		gr.setValue(attribute, value);
		if (!gr.update())
			gs.error('Error setting ' + attribute + 'field in sys_dictionary for the table sn_hr_core_bulk_case_request and column' + element + ' : ' + gr.getLastErrorMessage());
	}
}
